context: {
content: '',
hasChanges: false,
},
states: {
idle: {
on: {
EDIT: 'editing',
LOAD: 'loading',
},
},
loading: {
invoke: {
src: 'loadDocument',
onDone: {
target: 'idle',
actions: 'setContent',
},
onError: 'error',
},
},
editing: {
on: {
SAVE: 'saving',
CANCEL: 'idle',
TYPE: {
actions: 'updateContent',
},
},
},
saving: {
