let value = frm.doc.field_name;
// Read
frm.refresh_field('field_name'); // Refresh UI
```
All methods available in frappe.ui.form.on() handlers.

description:
:m The `frm` object in JavaScript provides methods to manipulate the form. Available in all event handlers:
**Setting values**:
```javascript
frm.set_value('field_name', value);
// Set field value
frm.set_df_property('field_name', 'read_only', 1);
// Make read-only
frm.set_df_property('field_name', 'hidden', 1);
// Hide field
frm.set_df_property('field_name', 'reqd', 1);
// Make required
```
**Field manipulation**:
```javascript
frm.toggle_display('field_name', condition);
// Show/hide
frm.toggle_reqd('field_name', condition);
// Required/optional
frm.toggle_enable('field_name', condition);
// Enable/disable
```
**Buttons**:
```javascript
frm.add_custom_button('Label', callback);
frm.remove_custom_button('Label');
```
**Refresh**:
```javascript
frm.refresh_field('field_name');
// Refresh specific field
frm.reload_doc();
// Reload entire document
```
**Data access**:
```javascript
frm.doc.field_name
// Read field value
frm.doc.items[0]
// Access child table row
```

