:m PLEG is the kubelet's mechanism to detect pod state changes efficiently. Instead of polling all containers constantly, it relies on the container runtime to report events.
```go
// PLEG generates pod lifecycle events
type GenericPLEG struct {
runtime
RuntimeService
eventCh
chan *PodLifecycleEvent
relistPeriod time.Duration
}
func (g *GenericPLEG) relist() {
// 1. Get current pods from runtime
currentPods := g.runtime.GetPods()
// 2. Compare with previous state
for _, pod := range currentPods {
oldPod := g.cache[pod.ID]
// 3. Detect changes and generate events
if oldPod == nil {
g.eventCh <- &PodLifecycleEvent{
ID:
pod.ID,
Type: ContainerStarted,
}
} else if pod.State != oldPod.State {
g.eventCh <- &PodLifecycleEvent{
ID:
pod.ID,
Type: ContainerChanged,
}
}
}
// 4. Update cache
g.cache = currentPods
}
```

:m SharedIndexInformer efficiently watches resources and maintains a local cache with indexing support. Multiple controllers can share one informer.
```go
// SharedIndexInformer structure
type sharedIndexInformer struct {
indexer
Indexer
// Local cache with indexes
controller Controller
// Manages watch connection
processor
*sharedProcessor
// Distributes events to listeners
listerWatcher ListerWatcher
// List/Watch interface
}
func (s *sharedIndexInformer) Run(stopCh <-chan struct{}) {
// 1. List all resources initially
list := s.listerWatcher.List()
s.indexer.Replace(list)
// 2. Start watch from resourceVersion
watcher := s.listerWatcher.Watch(list.ResourceVersion)
// 3. Process watch events
for event := range watcher.ResultChan() {
switch event.Type {
case Added:
s.indexer.Add(event.Object)
s.processor.distribute(event)
case Modified:
s.indexer.Update(event.Object)
s.processor.distribute(event)
case Deleted:
s.indexer.Delete(event.Object)
s.processor.distribute(event)
}
}
}
// Multiple controllers share one informer
podInformer := factory.Core().V1().Pods().Informer()
podInformer.AddEventHandler(handler1)
// Controller 1
podInformer.AddEventHandler(handler2)
// Controller 2
// Only ONE watch connection to API server
