:m Workqueues manage processing items with rate limiting to prevent overwhelming the system during failures.
```go
// Rate limiting queue with exponential backoff
queue := workqueue.NewRateLimitingQueue(
workqueue.DefaultControllerRateLimiter())
// Processing pattern
func (c *Controller) processNextItem() bool {
key, shutdown := c.queue.Get()
if shutdown {
return false
}
defer c.queue.Done(key)
err := c.syncHandler(key)
if err == nil {
// Success - remove from queue
c.queue.Forget(key)
return true
}
// Failed - requeue with backoff
if c.queue.NumRequeues(key) < 5 {
c.queue.AddRateLimited(key)
// Exponential backoff
return true
}
// Too many failures - give up
c.queue.Forget(key)
return true
}
// Rate limiter adds delays
type rateLimiter struct {
failures map[interface{}]int
baseDelay time.Duration
maxDelay
time.Duration
}
func (r *rateLimiter) When(item interface{}) time.Duration {
exp := r.failures[item]
r.failures[item]++
// delay = baseDelay * 2^exp
delay := r.baseDelay * time.Duration(1<<exp)
if delay > r.maxDelay {
delay = r.maxDelay
}
return delay
}
```

:m Only one replica of a controller should be active. Leader election ensures high availability without duplicate reconciliation.
```go
import "k8s.io/client-go/tools/leaderelection"
func runWithLeaderElection(clientset kubernetes.Interface) {
lock := &resourcelock.LeaseLock{
LeaseMeta: metav1.ObjectMeta{
Name:
"controller-leader",
Namespace: "kube-system",
},
Client: clientset.CoordinationV1(),
LockConfig: resourcelock.ResourceLockConfig{
Identity: hostname,
// Unique identity
},
}
leaderelection.RunOrDie(context.TODO(), leaderelection.LeaderElectionConfig{
Lock:
lock,
LeaseDuration: 15 * time.Second,
RenewDeadline: 10 * time.Second,
RetryPeriod:
2 * time.Second,
Callbacks: leaderelection.LeaderCallbacks{
OnStartedLeading: func(ctx context.Context) {
// This replica is now leader - start work
runController(ctx)
},
OnStoppedLeading: func() {
// Lost leadership - stop work
os.Exit(0)
},
},
})
}
// Lease mechanism
// Leader periodically updates lease.spec.renewTime
// If renewTime + leaseDuration < now, lease is expired
// Other replicas try to acquire expired lease
