func (kl *Kubelet) Run() {
// Create channel
podUpdates := make(chan *Pod, 100)
// Buffered channel
// Start producer goroutine
go kl.watchPods(podUpdates)
// Start consumer goroutine
go kl.syncPods(podUpdates)
}
func (kl *Kubelet) watchPods(updates chan<- *Pod) {
