:m Kubernetes needs to copy objects without sharing memory. Deep copy creates independent copies of nested structures.
```go
// Shallow copy problem
func shallowCopyProblem() {
original := &Pod{
Labels: map[string]string{"app": "nginx"},
}
// Shallow copy - shares the map!
copy := *original
// Modifying copy affects original!
copy.Labels["env"] = "prod"
// original.Labels now also has "env": "prod"
}
// Deep copy solution - manual
func (in *Pod) DeepCopy() *Pod {
if in == nil {
return nil
}
out := new(Pod)
// Copy simple fields
out.Name = in.Name
out.Namespace = in.Namespace
// Deep copy map
if in.Labels != nil {
out.Labels = make(map[string]string, len(in.Labels))
for key, val := range in.Labels {
out.Labels[key] = val
}
}
// Deep copy slices
if in.Spec.Containers != nil {
out.Spec.Containers = make([]Container, len(in.Spec.Containers))
for i := range in.Spec.Containers {
// Recursively deep copy
out.Spec.Containers[i] = *in.Spec.Containers[i].DeepCopy()
}
}
// Deep copy pointers
if in.Status != nil {
out.Status = in.Status.DeepCopy()
}
return out
}
// Kubernetes auto-generates deep copy
// File: zz_generated.deepcopy.go (auto-generated)
// DeepCopy is an autogenerated deepcopy function, copying the receiver,
// creating a new Pod.
func (in *Pod) DeepCopy() *Pod {
if in == nil {
return nil
}
out := new(Pod)
in.DeepCopyInto(out)
return out
}
// DeepCopyInto is an autogenerated deepcopy function, copying the receiver,
// writing into out. in must be non-nil.
func (in *Pod) DeepCopyInto(out *Pod) {
*out = *in
if in.Labels != nil {
in, out := &in.Labels, &out.Labels
*out = make(map[string]string, len(*in))
for key, val := range *in {
(*out)[key] = val
}
}
in.Spec.DeepCopyInto(&out.Spec)
if in.Status != nil {
in, out := &in.Status, &out.Status
*out = new(PodStatus)
(*in).DeepCopyInto(*out)
}
}
// Usage
func modifyPodSafely(original *Pod) {
// Create independent copy
copy := original.DeepCopy()
// Modify copy - doesn't affect original
copy.Labels["modified"] = "true"
// original is unchanged
}
// Code generation marker
// +k8s:deepcopy-gen:interfaces=k8s.io/apimachinery/pkg/runtime.Object
type Pod struct {
// ...
}
