:m Kubernetes extensively uses wait/poll patterns for eventually consistent operations.
```go
import (
"k8s.io/apimachinery/pkg/util/wait"
"time"
)
// Poll until condition is met
func waitForPodRunning(clientset kubernetes.Interface, podName string) error {
return wait.PollImmediate(
1*time.Second,
// Poll interval
5*time.Minute,
// Timeout
func() (bool, error) {
// Condition function
pod, err := clientset.CoreV1().
Pods("default").
Get(context.TODO(), podName, metav1.GetOptions{})
if err != nil {
return false, err
// Error, stop polling
}
if pod.Status.Phase == v1.PodRunning {
return true, nil
// Success, stop polling
}
return false, nil
// Not ready, continue polling
},
)
}
// Poll with backoff
func waitWithBackoff() error {
backoff := wait.Backoff{
Duration: 1 * time.Second,
// Initial duration
Factor:
2.0,
// Multiply by this each iteration
Steps:
5,
// Maximum steps
Cap:
1 * time.Minute,
// Maximum duration
}
return wait.ExponentialBackoff(backoff, func() (bool, error) {
// Try operation
err := attemptOperation()
if err == nil {
return true, nil
// Success
}
return false, nil
// Retry with backoff
})
}
// Poll forever (use with context for cancellation)
func pollForever(ctx context.Context) {
wait.UntilWithContext(ctx,
func(ctx context.Context) {
// Do work periodically
doWork()
},
30*time.Second,
// Period
)
}
// Jittered wait (adds randomness to avoid thundering herd)
func waitWithJitter() {
wait.JitterUntil(
func() {
doWork()
},
30*time.Second,
// Period
0.1,
// Jitter factor (10%)
true,
// Sliding (reset timer after work)
stopCh,
// Stop signal
)
}
// Real Kubernetes example: Wait for CRD to be established
func waitForCRD(client apiextensionsclient.Interface, name string) error {
return wait.PollImmediate(500*time.Millisecond, 60*time.Second,
func() (bool, error) {
crd, err := client.ApiextensionsV1().
CustomResourceDefinitions().
Get(context.TODO(), name, metav1.GetOptions{})
if err != nil {
return false, err
}
// Check if CRD is established
for _, cond := range crd.Status.Conditions {
if cond.Type == apiextensionsv1.Established &&
cond.Status == apiextensionsv1.ConditionTrue {
return true, nil
}
}
return false, nil
},
)
}
```

:m The kubelet is the primary node agent running on each Kubernetes worker node. It ensures containers are running in pods according to PodSpecs received from the API server.
The kubelet's main loop continuously:
```go
// Pseudocode of kubelet's main sync loop
func (kl *Kubelet) syncLoop() {
for {
// 1. Get pod updates from API server
pods := kl.getPodUpdates()
// 2. Sync each pod
for _, pod := range pods {
kl.SyncPod(pod)
}
// 3. Perform housekeeping
kl.cleanupPods()
// 4. Wait for next iteration
time.Sleep(syncFrequency)
}
}
