func (dsc *DaemonSetsController) nodeShouldRunDaemonPod(node *Node, ds *DaemonSet) (bool, bool) {
// Check if node is schedulable
if node.Spec.Unschedulable && !ds.Spec.Template.Spec.HostNetwork {
return false, false
}
// Check node selector
if !nodeMatchesSelector(node, ds.Spec.Template.Spec.NodeSelector) {
return false, false
}
// Check node affinity
if !nodeMatchesAffinity(node, ds.Spec.Template.Spec.Affinity) {
return false, false
}
// Check taints and tolerations
for _, taint := range node.Spec.Taints {
if taint.Effect == NoSchedule || taint.Effect == NoExecute {
if !podToleratesTaint(ds.Spec.Template.Spec.Tolerations, taint) {
return false, false
}
}
}
return true, true
}
// Rolling update for DaemonSet
func (dsc *DaemonSetsController) rollingUpdate(ds *DaemonSet) error {
// Get update strategy
strategy := ds.Spec.UpdateStrategy
if strategy.Type != apps.RollingUpdateDaemonSetStrategyType {
return nil
}
// MaxUnavailable determines how many pods can be down during update
maxUnavailable := getMaxUnavailable(strategy.RollingUpdate)
// Get all daemon pods
allPods := dsc.getDaemonPods(ds)
// Count how many are unavailable
unavailableCount := 0
for _, pod := range allPods {
if !isPodAvailable(pod) {
unavailableCount++
}
}
// Find pods that need update
oldPods := []*Pod{}
for _, pod := range allPods {
if getPodGeneration(pod) != ds.Generation {
oldPods = append(oldPods, pod)
}
}
// Delete old pods up to maxUnavailable limit
for _, pod := range oldPods {
if unavailableCount >= maxUnavailable {
break
}
dsc.podControl.DeletePod(ds.Namespace, pod.Name)
unavailableCount++
}
return nil
}
```

:m Location: `pkg/controller/job/`
Job runs pods to completion with retry logic and parallelism control.
```go
// Job controller in pkg/controller/job/job_controller.go
type Controller struct {
jobLister corelisters.JobLister
podLister corelisters.PodLister
}
func (jm *Controller) syncJob(key string) error {
job := jm.jobLister.Jobs(namespace).Get(name)
// 1. Get pods for this job
pods := jm.getPodsForJob(job)
// 2. Count pod states
active := 0
succeeded := 0
failed := 0
for _, pod := range pods {
switch pod.Status.Phase {
case v1.PodRunning, v1.PodPending:
active++
case v1.PodSucceeded:
succeeded++
case v1.PodFailed:
failed++
}
}
// 3. Check if job is finished
var jobFinished bool
var finishedCondition *JobCondition
// Success condition
if job.Spec.Completions == nil {
// No completions specified - complete when any pod succeeds
if succeeded > 0 {
jobFinished = true
finishedCondition = &JobCondition{
Type:
JobComplete,
Status: ConditionTrue,
}
}
} else {
// Complete when succeeded >= completions
if succeeded >= int(*job.Spec.Completions) {
jobFinished = true
finishedCondition = &JobCondition{
Type:
JobComplete,
Status: ConditionTrue,
}
}
}
// Failure condition
if job.Spec.BackoffLimit != nil {
if failed > int(*job.Spec.BackoffLimit) {
jobFinished = true
finishedCondition = &JobCondition{
Type:
JobFailed,
Status: ConditionTrue,
Reason: "BackoffLimitExceeded",
}
}
}
if jobFinished {
// 4. Job is finished, update condition and return
job.Status.Conditions = append(job.Status.Conditions, *finishedCondition)
jm.updateJobStatus(job)
return nil
}
// 5. Job not finished, manage active pods
// Calculate desired active pods
wantActive := 0
if job.Spec.Completions == nil {
// Run parallelism pods
wantActive = int(*job.Spec.Parallelism)
} else {
// Run min(parallelism, completions - succeeded)
remaining := int(*job.Spec.Completions) - succeeded
wantActive = min(remaining, int(*job.Spec.Parallelism))
}
diff := active - wantActive
if diff < 0 {
// Need to create pods
diff *= -1
// Limit burst creation
if diff > maxBatchSize {
diff = maxBatchSize
}
// Check backoff for failed pods
if jm.shouldBackoff(job, pods) {
return nil
}
for i := 0; i < diff; i++ {
pod := jm.newPodFromTemplate(&job.Spec.Template, job)
jm.podControl.CreatePod(job.Namespace, pod)
}
} else if diff > 0 {
// Too many active pods, delete some
podsToDelete := getPodsToDelete(pods, diff)
for _, pod := range podsToDelete {
jm.podControl.DeletePod(job.Namespace, pod.Name)
}
}
// 6. Update job status
job.Status.Active = int32(active)
job.Status.Succeeded = int32(succeeded)
job.Status.Failed = int32(failed)
jm.updateJobStatus(job)
return nil
}
// Backoff calculation
func (jm *Controller) shouldBackoff(job *Job, pods []*Pod) bool {
// Exponential backoff: 10s, 20s, 40s, 80s, 160s, 320s (max 6 minutes)
failureCount := countFailedPods(pods)
if failureCount == 0 {
return false
}
lastFailureTime := getLastFailureTime(pods)
backoffDuration := getBackoffDuration(failureCount)
return time.Since(lastFailureTime) < backoffDuration
}
func getBackoffDuration(failureCount int) time.Duration {
// 10s * 2^failures, max 6 minutes
duration := 10 * time.Second * time.Duration(1<<failureCount)
maxDuration := 6 * time.Minute
if duration > maxDuration {
duration = maxDuration
}
return duration
}
```

:m Location: `pkg/controller/cronjob/`
CronJob creates Jobs on a schedule.
```go
// CronJob controller in pkg/controller/cronjob/cronjob_controller.go
type Controller struct {
cronJobLister batchlisters.CronJobLister
jobLister
batchlisters.JobLister
}
func (c *Controller) syncCronJob(key string) error {
cronJob := c.cronJobLister.CronJobs(namespace).Get(name)
// 1. Get jobs owned by this CronJob
jobs := c.getJobsForCronJob(cronJob)
// 2. Clean up finished jobs based on history limits
c.cleanupFinishedJobs(cronJob, jobs)
// 3. Check if suspended
if cronJob.Spec.Suspend != nil && *cronJob.Spec.Suspend {
return nil
}
// 4. Parse schedule
schedule, err := cron.ParseStandard(cronJob.Spec.Schedule)
if err != nil {
return err
}
// 5. Calculate next scheduled time
var earliestTime time.Time
if cronJob.Status.LastScheduleTime != nil {
earliestTime = cronJob.Status.LastScheduleTime.Time
} else {
earliestTime = cronJob.ObjectMeta.CreationTimestamp.Time
}
missedRuns, nextRun := c.getMissedRunsAndNextScheduledTime(schedule, earliestTime, time.Now())
// 6. Handle concurrency policy for missed runs
if len(missedRuns) > 0 {
switch cronJob.Spec.ConcurrencyPolicy {
case batch.AllowConcurrent:
// Create job for each missed run
for _, scheduledTime := range missedRuns {
c.createJob(cronJob, scheduledTime)
}
case batch.ForbidConcurrent:
// Only create if no active jobs
if len(c.getActiveJobs(jobs)) == 0 {
// Create for most recent missed run
c.createJob(cronJob, missedRuns[len(missedRuns)-1])
}
case batch.ReplaceConcurrent:
// Delete active jobs and create new one
for _, job := range c.getActiveJobs(jobs) {
c.jobControl.DeleteJob(job.Namespace, job.Name)
}
c.createJob(cronJob, missedRuns[len(missedRuns)-1])
}
}
// 7. Schedule next sync
timeUntilNextRun := nextRun.Sub(time.Now())
c.queue.AddAfter(key, timeUntilNextRun)
// 8. Update status
cronJob.Status.LastScheduleTime = &metav1.Time{Time: missedRuns[len(missedRuns)-1]}
c.updateCronJobStatus(cronJob)
return nil
}
func (c *Controller) createJob(cronJob *CronJob, scheduledTime time.Time) error {
// 1. Build job from template
job := &Job{
ObjectMeta: metav1.ObjectMeta{
Name:
fmt.Sprintf("%s-%d", cronJob.Name, scheduledTime.Unix()),
Namespace: cronJob.Namespace,
Labels:
cronJob.Spec.JobTemplate.Labels,
Annotations: map[string]string{
"cronjob.kubernetes.io/scheduled-at": scheduledTime.Format(time.RFC3339),
},
OwnerReferences: []metav1.OwnerReference{
*metav1.NewControllerRef(cronJob, batch.SchemeGroupVersion.WithKind("CronJob")),
},
},
Spec: cronJob.Spec.JobTemplate.Spec,
}
// 2. Create job
return c.jobControl.CreateJob(cronJob.Namespace, job)
}
func (c *Controller) cleanupFinishedJobs(cronJob *CronJob, jobs []*Job) {
// Separate successful and failed jobs
successfulJobs := []*Job{}
failedJobs := []*Job{}
for _, job := range jobs {
if isJobFinished(job) {
if isJobSucceeded(job) {
successfulJobs = append(successfulJobs, job)
} else {
failedJobs = append(failedJobs, job)
}
}
}
// Sort by creation timestamp (oldest first)
sort.Sort(byCreationTimestamp(successfulJobs))
sort.Sort(byCreationTimestamp(failedJobs))
// Delete old successful jobs
if cronJob.Spec.SuccessfulJobsHistoryLimit != nil {
limit := int(*cronJob.Spec.SuccessfulJobsHistoryLimit)
for i := 0; i < len(successfulJobs)-limit; i++ {
c.jobControl.DeleteJob(successfulJobs[i].Namespace, successfulJobs[i].Name)
}
}
// Delete old failed jobs
if cronJob.Spec.FailedJobsHistoryLimit != nil {
limit := int(*cronJob.Spec.FailedJobsHistoryLimit)
for i := 0; i < len(failedJobs)-limit; i++ {
c.jobControl.DeleteJob(failedJobs[i].Namespace, failedJobs[i].Name)
}
}
}
```

example:
:m The **Action system** is the standardized interface for all user operations in Excalidraw.
**Key parts of an Action:**
```typescript
interface Action {
// 1. Identity
name: string;
// "delete", "copy", "changeColor"
label: string;
// "Delete" (for UI)
// 2. The operation
perform: (elements, appState, formData, app) => {
return {
elements: updatedElements,
// Modified elements
appState: updatedAppState,
// Modified state
storeAction: StoreAction.CAPTURE // Undo/redo behavior
};
},
// 3. Keyboard shortcut (optional)
keyTest: (event) => event.key === "Delete",
// 4. Availability check (optional)
predicate: (elements, appState) =>
hasSelectedElements(appState),
// 5. Context menu (optional)
contextItemLabel: "Delete"
}
```
**Benefits:**
- Unified logic for keyboard, toolbar, menu
- Automatic undo/redo integration
- Consistent behavior across triggers
- Easy to test in isolation
Located in: `packages/excalidraw/actions/`

description:
:m The Action system in Excalidraw is the standardized way to perform all user operations. Instead of scattered event handlers modifying state directly, actions provide a unified interface: they receive elements and appState, perform operations, and return updated elements and appState. This architecture enables consistent undo/redo, keyboard shortcuts, toolbar buttons, and context menus to all trigger the same logic. Every user operation (copy, paste, delete, change color, etc.) is implemented as an action.
```typescript
// Action interface
interface Action {
name: string;
// Unique identifier
label: string;
// Human-readable name
perform: (
// The actual operation
elements: ExcalidrawElement[],
appState: AppState,
formData: any,
app: AppClassProperties
) => ActionResult;
keyTest?: (event: KeyboardEvent) => boolean;
// Keyboard shortcut
predicate?: (elements, appState) => boolean;
// When action is available
contextItemLabel?: string;
// Context menu text
}
// Example: Delete action
const actionDelete = {
name: "delete",
perform: (elements, appState) => ({
elements: elements.map(el =>
appState.selectedElementIds[el.id]
: el
),
appState,
storeAction: StoreAction.CAPTURE
// Enable undo
}),
keyTest: (e) => e.key === "Delete" || e.key === "Backspace"
};
```

example:
:m The **perform function** executes the action's logic.
**Four parameters:**
```typescript
perform: (
// 1. elements - Current elements array
elements: readonly ExcalidrawElement[],
// 2. appState - Current application state
appState: Readonly<AppState>,
// 3. formData - User input from UI
formData: any,
// 4. app - App instance with utilities
app: AppClassProperties
) => ActionResult
```
**Must return ActionResult:**
```typescript
{
elements?: ExcalidrawElement[],
// Updated elements
appState?: AppState,
// Updated state
storeAction: StoreAction
// Undo/redo control
}
```
**Example:**
```typescript
perform: (elements, appState, formData, app) => {
const newElements = elements.map(el =>
appState.selectedElementIds[el.id]
? mutateElement(el, { x: el.x + 10 })
: el
);
return {
elements: newElements,
appState,
storeAction: StoreAction.CAPTURE
// Enable undo
};
}
```
**Pattern:** Read → Compute immutably → Return

description:
:m The perform function is the heart of an action - it contains the actual logic. It receives four parameters: elements array, current appState, formData (from UI inputs), and app instance (for utilities). It must return an ActionResult object containing updated elements, updated appState, and a storeAction flag that tells the undo/redo system whether to capture this change. The pattern is always: read current state, compute changes immutably, return new state.
```typescript
// perform function signature
type ActionPerform = (
elements: readonly ExcalidrawElement[],
appState: Readonly<AppState>,
formData: any,
app: AppClassProperties
) => ActionResult;
// ActionResult structure
interface ActionResult {
elements?: ExcalidrawElement[];
// Updated elements
appState?: AppState;
// Updated state
storeAction: StoreAction;
// Undo/redo behavior
}
// Example implementation
perform: (elements, appState, formData, app) => {
// 1. Read current state
const selectedIds = appState.selectedElementIds;
// 2. Compute new state immutably
const newElements = elements.map(el =>
selectedIds[el.id]
: el
);
// 3. Return result
return {
elements: newElements,
appState,
// Unchanged in this case
storeAction: StoreAction.CAPTURE
// Save for undo
};
}
```

example:
:m **StoreAction** controls how actions interact with the undo/redo system.
**Three values:**
```typescript
enum StoreAction {
// 1. CAPTURE - Create new undo entry
CAPTURE = "capture",
// 2. NONE - Don't save for undo
NONE = "none",
// 3. UPDATE - Modify current undo entry
UPDATE = "update"
}
```
**When to use each:**
```typescript
// CAPTURE - User should be able to undo this
actionDelete.perform = () => ({
elements: deletedElements,
storeAction: StoreAction.CAPTURE
// User can press Ctrl+Z to undo deletion
});
// NONE - Not an undoable action
actionZoom.perform = () => ({
appState: { ...appState, zoom: 2 },
storeAction: StoreAction.NONE
// Zooming is not undoable
});
// UPDATE - Continuous operation (drag, resize)
onDrag.perform = () => ({
elements: draggedElements,
storeAction: StoreAction.UPDATE
// Updates existing undo entry
// One undo for entire drag, not each pixel
});
```
**Result:** Fine-grained control over what's undoable.

description:
:m The storeAction field in ActionResult controls how the action interacts with the undo/redo system. StoreAction.CAPTURE means "save this state change for undo/redo", StoreAction.NONE means "don't save this change", and StoreAction.UPDATE means "update the current undo state without creating a new entry". This fine-grained control allows actions to decide whether they should be undoable (like deletions) or not (like zooming).
```typescript
enum StoreAction {
CAPTURE = "capture",
// Save as new undo state
NONE = "none",
// Don't save
UPDATE = "update"
// Update current undo state
}
// Example: Delete action (should be undoable)
return {
elements: deletedElements,
appState,
storeAction: StoreAction.CAPTURE
// ✅ User can undo deletion
};
// Example: Zoom action (shouldn't be undoable)
return {
appState: { ...appState, zoom: { value: 2 } },
storeAction: StoreAction.NONE
// ❌ Can't undo zoom
};
// Example: Continuous drag (update current undo entry)
// While dragging, update position continuously
// Only create one undo entry for the entire drag
return {
elements: movedElements,
appState,
storeAction: StoreAction.UPDATE
// 🔄 Update current undo
};
```

example:
:m **keyTest** defines keyboard shortcuts for actions.
**Basic structure:**
```typescript
keyTest: (event: KeyboardEvent) => boolean
// Example: Delete key
keyTest: (event) => {
return event.key === "Delete" || event.key === "Backspace";
}
```
**Cross-platform modifiers:**
```typescript
// ✅ CORRECT - Works on Mac (Cmd) and Windows (Ctrl)
keyTest: (event) => {
const cmdOrCtrl = event.metaKey || event.ctrlKey;
return cmdOrCtrl && event.key.toLowerCase() === "c";
}
// ❌ WRONG - Only works on Windows
keyTest: (event) => {
return event.ctrlKey && event.key === "c";
}
```
**Common patterns:**
```typescript
// Copy: Cmd/Ctrl + C
(event.ctrlKey || event.metaKey) &&
event.key === "c" &&
!event.shiftKey
// Paste: Cmd/Ctrl + V
(event.ctrlKey || event.metaKey) &&
event.key === "v"
// Duplicate: Cmd/Ctrl + D
(event.ctrlKey || event.metaKey) &&
event.key === "d"
// Save: Cmd/Ctrl + S
(event.ctrlKey || event.metaKey) &&
event.key === "s"
```
**Key checks:**
- `event.key` - The key pressed
- `event.ctrlKey` - Ctrl key (Windows/Linux)
- `event.metaKey` - Cmd key (Mac)
- `event.shiftKey` - Shift modifier
- `event.altKey` - Alt/Option modifier

description:
:m The keyTest function determines if a keyboard event should trigger the action. It receives a KeyboardEvent and returns a boolean. You check for specific key combinations using event.key, event.ctrlKey, event.metaKey (Cmd on Mac), event.shiftKey, and event.altKey. The function should handle cross-platform differences (Ctrl on Windows/Linux, Cmd on Mac) and avoid conflicts with existing shortcuts.
```typescript
// keyTest function signature
keyTest?: (event: KeyboardEvent) => boolean;
// Example: Delete action (Delete or Backspace)
keyTest: (event) => {
return event.key === "Delete" || event.key === "Backspace";
}
// Example: Copy (Ctrl+C or Cmd+C)
keyTest: (event) => {
return (event.ctrlKey || event.metaKey) &&
event.key.toLowerCase() === "c" &&
!event.shiftKey &&
!event.altKey;
}
// Example: Duplicate (Ctrl+D)
keyTest: (event) => {
return (event.ctrlKey || event.metaKey) &&
event.key.toLowerCase() === "d" &&
!event.shiftKey;
}
// Cross-platform helper pattern
keyTest: (event) => {
// Check modifier based on platform
const modifier = event.ctrlKey || event.metaKey;
return modifier && event.key === "s";
}
```

example:
:m **predicate** determines when an action should be available in the UI.
**Signature:**
```typescript
predicate: (
elements: readonly ExcalidrawElement[],
appState: AppState
) => boolean
```
**Use cases:**
```typescript
// 1. Only show when elements selected
predicate: (elements, appState) => {
return Object.keys(appState.selectedElementIds)
.some(id => appState.selectedElementIds[id]);
}
// Result: Delete button disabled when nothing selected
// 2. Only for specific element types
predicate: (elements, appState) => {
const selected = getSelectedElements(elements, appState);
return selected.some(el =>
el.type === "rectangle" || el.type === "diamond"
);
}
// Result: "Round Corners" only for rectangles/diamonds
// 3. Only when multiple selected
predicate: (elements, appState) => {
const count = Object.values(appState.selectedElementIds)
.filter(Boolean).length;
return count > 1;
}
// Result: "Align" actions need 2+ elements
// 4. Only when state permits
predicate: (elements, appState) => {
return appState.clipboardData != null;
}
// Result: "Paste" only when clipboard has data
```
**Benefits:** Context-aware UI, disabled buttons when not applicable, cleaner menus.

description:
:m The predicate function determines when an action should be available or visible in the UI. It receives elements and appState and returns a boolean. This allows actions to only appear in context menus when relevant (e.g., "Bring to Front" only when elements are selected) or to disable toolbar buttons when the action can't be performed. The predicate is evaluated frequently, so it should be efficient.
```typescript
// predicate function signature
predicate?: (
elements: readonly ExcalidrawElement[],
appState: AppState
) => boolean;
// Example: Only show when elements are selected
predicate: (elements, appState) => {
const selectedIds = appState.selectedElementIds;
return Object.keys(selectedIds).some(id => selectedIds[id]);
}
// Example: Only for text elements
predicate: (elements, appState) => {
const selected = getSelectedElements(elements, appState);
return selected.some(el => el.type === "text");
}
// Example: Only when multiple elements selected
predicate: (elements, appState) => {
const selectedCount = Object.values(
appState.selectedElementIds
).filter(Boolean).length;
return selectedCount > 1;
// Need at least 2 for align
}
// Example: Clipboard actions need clipboard data
predicate: (elements, appState) => {
return appState.clipboardData != null;
}
```

example:
:m **Action registration** makes actions available throughout Excalidraw.
**How to register:**
```typescript
import { register } from "./register";
export const actionMyAction = register({
name: "myAction",
label: "My Action",
perform: (elements, appState) => {
// Implementation
return { elements, appState, storeAction: StoreAction.CAPTURE };
},
keyTest: (e) => e.key === "m",
contextItemLabel: "Do My Action"
});
// Export in actions/index.tsx
export { actionMyAction } from "./actionMyAction";
```
**Four ways to trigger:**
```typescript
// 1. Keyboard shortcut (automatic)
// User presses 'm' → action executes via keyTest
// 2. Toolbar button
<button onClick={() =>
actionMyAction.perform(elements, appState)
}>
My Action
</button>
// 3. Context menu (automatic)
// Right-click → "Do My Action" → executes via contextItemLabel
// 4. Programmatically
const result = actionMyAction.perform(
elements,
appState,
formData,
app
);
```
**Result:** One action definition, multiple trigger points with consistent behavior.

description:
:m Actions must be registered to be used in Excalidraw. The register function wraps the action definition and adds it to the action manager. Once registered, actions can be triggered via keyboard shortcuts, toolbar buttons, context menus, or programmatically. The registration also validates the action definition and sets up the keyboard event listeners.
```typescript
// Import register function
import { register } from "./register";
// Define and register action in one step
export const actionChangeStrokeColor = register({
name: "changeStrokeColor",
label: "Change stroke color",
perform: (elements, appState, formData) => {
// ... implementation
},
// ... other properties
});
// Later, action can be triggered in multiple ways:
// 1. Via keyboard (automatic via keyTest)
// User presses Ctrl+S → action executes
// 2. Via toolbar button
<button onClick={() =>
actionChangeStrokeColor.perform(elements, appState, formData)
}>
Change Color
</button>
// 3. Via context menu (automatic via contextItemLabel)
// Right-click → "Change stroke color" → action executes
// 4. Programmatically
const result = actionChangeStrokeColor.perform(
elements,
appState,
{ color: "#ff0000" },
app
);
```

:m Excalidraw has 44+ actions organized into logical categories. Canvas actions control the view (zoom, grid), clipboard actions handle copy/paste, property actions modify element appearance (color, stroke, opacity), editing actions manipulate elements (delete, duplicate, align), navigation actions control viewport (scroll, zoom to fit), and history actions handle undo/redo. Understanding these categories helps you find existing actions and know where to add new ones.
```typescript
// Action categories with examples
// CANVAS: View and canvas settings
- actionToggleGrid
// Show/hide grid
- actionToggleStats
// Show statistics
- actionZoomIn/Out
// Zoom controls
// CLIPBOARD: Copy/paste operations
- actionCopy
// Ctrl+C
- actionPaste
// Ctrl+V
- actionCut
// Ctrl+X
- actionCopyAsPng
// Export as image
// PROPERTIES: Element appearance
- actionChangeStrokeColor
// Border color
- actionChangeBackgroundColor
// Fill color
- actionChangeStrokeWidth
// Border thickness
- actionChangeOpacity
// Transparency
// EDITING: Element manipulation
- actionDeleteSelected
// Delete
- actionDuplicateSelection
// Duplicate
- actionFlipHorizontal
// Flip
- actionAlignLeft/Right
// Alignment
// NAVIGATION: Viewport control
- actionZoomToFit
// Fit to screen
- actionZoomToSelection
// Focus selected
// HISTORY: Undo/redo
- actionUndo
// Ctrl+Z
- actionRedo
// Ctrl+Shift+Z
```

example:
:m Actions integrate with the **context menu** (right-click menu) automatically.
**Required properties:**
```typescript
export const actionMyAction = register({
name: "myAction",
// 1. Label for context menu
contextItemLabel: "Do My Action",
// 2. When to show (optional but recommended)
predicate: (elements, appState) => {
return hasSelectedElements(appState);
},
perform: (elements, appState) => {
// ... implementation
}
});
```
**How it works:**
```typescript
// User right-clicks
onContextMenu(event) {
const menuItems = [];
// For each registered action
for (const action of allActions) {
// Check if action has context menu label
if (action.contextItemLabel) {
// Check if action is available
if (!action.predicate || action.predicate(elements, appState)) {
// Add to menu
menuItems.push({
label: action.contextItemLabel,
onClick: () => action.perform(elements, appState)
});
}
}
}
// Show context menu with items
showContextMenu(menuItems);
}
```
**Result:**
- User right-clicks → sees "Do My Action"
- Clicks → perform executes
- Only shows when predicate returns true

description:
:m Actions can automatically appear in the context menu (right-click menu) by setting the contextItemLabel property. When a user right-clicks, Excalidraw evaluates each action's predicate to determine if it should be shown, then displays the actions with their contextItemLabel. This provides a discoverable way for users to access actions beyond keyboard shortcuts.
```typescript
// Action with context menu integration
export const actionBringToFront = register({
name: "bringToFront",
label: "Bring to Front",
// Text shown in context menu
contextItemLabel: "Bring to front",
// Only show when elements are selected
predicate: (elements, appState) => {
return Object.values(appState.selectedElementIds)
.some(Boolean);
},
perform: (elements, appState) => {
// Move selected elements to end of array (renders on top)
// ... implementation
},
keyTest: (e) => (e.ctrlKey || e.metaKey) && e.key === "]"
});
// Context menu rendering (automatic)
// User right-clicks → Excalidraw checks all actions
// For each action:
//
- If predicate returns true
//
- And contextItemLabel is defined
//
- Show menu item with contextItemLabel text
//
- Click → execute perform function
```

